postprocess_passes.code:
text = " ".join(str(input_text or "").split())
if not text:
    return None
cleaned = re.sub(r"(?i)\b27\b\s*[.:)]?\s*(?:what\s+is\s+your\s+age\??|age\??)", " ", text)
cleaned = " ".join(cleaned.split()).strip(' :;,.?"\'()[]{}')
if not cleaned:
    return None
fixed = re.sub(r"(?i)(?<![A-Za-z0-9])[il](?=\d)", "1", cleaned)
nums = re.findall(r"(?<!\d)(\d{1,2})(?!\d)", fixed)
num_values = []
for n in nums:
    if n != "27" and n not in num_values:
        num_values.append(n)
if len(num_values) == 1:
    return num_values[0]
return cleaned
